import {CodeArtifact, FEATURE, FeatureModule} from '../types';
import {Hex} from 'viem';
import {testExecuteProposal} from '../utils/constants';
import {addressPrompt, translateJsAddressToSol} from '../prompts/addressPrompt';
import {CHAIN_TO_CHAIN_ID, getExplorerLink, getMarketChain} from '../common';

/**
 * `address` is the legacy single-address shape and is kept so existing config files keep working.
 * New configs generated by the cli use `addresses`.
 */
export type FlashBorrower = {address: Hex} | {addresses: Hex[]};

export function getFlashBorrowerAddresses(cfg: FlashBorrower): Hex[] {
  return 'addresses' in cfg ? cfg.addresses : [cfg.address];
}

export const flashBorrower: FeatureModule<FlashBorrower> = {
  value: FEATURE.FLASH_BORROWER,
  description: 'FlashBorrower (whitelist addresses as 0% fee flashborrowers)',
  async cli({market}) {
    console.log(`Fetching information for FlashBorrower on ${market}`);
    const addresses: Hex[] = [
      await addressPrompt({
        message: 'Who do you want to grant the flashBorrower role',
        required: true,
      }),
    ];
    while (true) {
      const address = await addressPrompt({
        message: 'Who else do you want to grant the flashBorrower role (leave empty to finish)',
        required: false,
      });
      if (!address) break;
      addresses.push(address);
    }
    const response: FlashBorrower = {addresses};
    return response;
  },
  build({market, cfg}) {
    const addresses = getFlashBorrowerAddresses(cfg);
    // a single address keeps the original constant name so regenerating existing configs is a no-op
    const names = addresses.map((_, i) =>
      addresses.length === 1 ? 'NEW_FLASH_BORROWER' : `NEW_FLASH_BORROWER_${i + 1}`,
    );
    const response: CodeArtifact = {
      code: {
        constants: addresses.map(
          (address, i) =>
            `// ${getExplorerLink(CHAIN_TO_CHAIN_ID[getMarketChain(market)], address)}\naddress public constant ${names[i]} = ${translateJsAddressToSol(address)};`,
        ),
        execute: names.map((name) => `${market}.ACL_MANAGER.addFlashBorrower(${name});`),
      },
      test: {
        fn: [
          `function test_isFlashBorrower() external {
          ${testExecuteProposal(market)}
          ${
            names.length === 1
              ? `bool isFlashBorrower = ${market}.ACL_MANAGER.isFlashBorrower(proposal.${names[0]}());
          assertEq(isFlashBorrower, true);`
              : names
                  .map(
                    (name) =>
                      `assertEq(${market}.ACL_MANAGER.isFlashBorrower(proposal.${name}()), true);`,
                  )
                  .join('\n          ')
          }
        }`,
        ],
      },
    };
    return response;
  },
};
